"""决战出征准备页 UI 控制器（决战专用版）。

继承自 :class:`~autowsgr.ui.battle.preparation.BattlePreparationPage`，
仅通过 ``_use_search = False`` 切换为 "不使用搜索框" 的换船模式。

与普通换船的差异
---------------
- 普通换船: 点击搜索框 -> 输入舰船名 -> 等待筛选结果 -> 点击第一项
- 决战换船: 直接 OCR 识别选船列表 -> 按编辑距离模糊匹配 -> 点击目标坐标

这是因为决战选船流程没有搜索框（界面为直接列表展示），
且候选集合相对固定（由配置 level1/level2 决定）。

换船算法 (扫描 -> 定点更换 -> 调整次序) 由父类
:class:`~autowsgr.ui.battle.fleet_change.FleetChangeMixin` 统一提供。
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from autowsgr.combat.fleet import exact_fleet_rules
from autowsgr.image_resources import Templates
from autowsgr.infra import ActionFailedError
from autowsgr.infra.logger import get_logger
from autowsgr.ui.battle.base import Panel
from autowsgr.ui.battle.constants import CLICK_BACK
from autowsgr.ui.battle.preparation import BattlePreparationPage
from autowsgr.ui.decisive.legacy_fleet_change import change_fleet_legacy
from autowsgr.ui.decisive.overlay import CLICK_REPAIR_ALL, is_decisive_map_page
from autowsgr.ui.utils import click_and_wait_for_page, wait_for_stable_screen
from autowsgr.ui.utils.navigation import NavConfig
from autowsgr.vision import ImageChecker


_log = get_logger('ui.decisive')


if TYPE_CHECKING:
    from collections.abc import Sequence

    from autowsgr.context import GameContext
    from autowsgr.infra import DecisiveConfig
    from autowsgr.vision import OCREngine


class DecisiveBattlePreparationPage(BattlePreparationPage):
    """决战出征准备页面控制器（无搜索框换船版）。

    与 :class:`BattlePreparationPage` 唯一的区别是
    ``_use_search = False``，使选船页面跳过搜索框，直接
    通过 DLL 行定位 + OCR 识别舰船列表并点击目标。

    Parameters
    ----------
    ctx:
        游戏上下文。
    config:
        决战配置。
    ocr:
        OCR 引擎（必须提供，换船时依赖 OCR）。
    """

    _use_search: bool = False

    def __init__(
        self,
        ctx: GameContext,
        config: DecisiveConfig,
        ocr: OCREngine | None = None,
    ) -> None:
        super().__init__(ctx, ocr)
        self._ocr: OCREngine = ocr or ctx.ocr  # type: ignore[assignment]
        self._config = config

    def change_fleet(
        self,
        fleet_id: int | None,
        ship_names: Sequence[str | None],
    ) -> bool:
        """按配置选择决战原有流程或新的换船算法。"""
        if self._config.use_new_fleet_change_algorithm:
            rules = exact_fleet_rules([name for name in ship_names if name])
            return super().change_fleet(fleet_id, rules)
        return change_fleet_legacy(self, fleet_id, ship_names)

    def ensure_fleet(self, target: list[str]) -> None:
        """把当前编队调整为 ``target``（7 槽位列表，索引 0 留空）。

        未满编时允许空槽，绝不使用非潜艇凑数。
        """
        wanted = [name or '' for name in target[1:7]]
        current = [name or '' for name in self.detect_fleet(self._ctrl.screenshot())]
        if current == wanted:
            _log.debug('[决战准备] 编队已是目标: {}', wanted)
            return
        _log.info('[决战准备] 调整编队: {} -> {}', current, wanted)
        if not self.change_fleet(None, wanted):
            raise ActionFailedError(f'决战编队未生效: 目标={wanted}, 实际={current}')
        _log.info('[决战准备] 编队调整完成: {}', wanted)

    def apply_full_repair(self) -> None:
        """切到快速修理页签并点击「全部修理」大按钮。

        v6 不再读取血条、不按槽位修理；是否修理由游戏弹窗驱动，
        这里只负责在进入准备页后一键修完。
        """
        _log.info('[决战准备] 快速修理 → 全部修理')
        self.select_panel(Panel.QUICK_REPAIR)
        screen = self._ctrl.screenshot()
        match = ImageChecker.find_template(
            screen,
            Templates.Decisive.REPAIR_ALL,
            confidence=0.82,
        )
        if match is not None:
            self._ctrl.click(*match.center)
        else:
            self._ctrl.click(*CLICK_REPAIR_ALL)

        # 不读血量；点完只等画面稳定，随后由上层点「开始出征」。
        wait_for_stable_screen(
            self._ctrl,
            timeout=1.5,
            interval=0.15,
            stable_frames=2,
            source='决战全部修理',
            stop_event=self._ctx.stop_event,
        )

    def go_back(self) -> None:
        """点击回退按钮 (◁)，返回**决战地图页**。

        基类 :meth:`BattlePreparationPage.go_back` 等待普通出征地图页
        (``PageName.MAP``)，而决战准备页回退后是决战地图页（不在页面
        注册表中，无 ``PageName``），沿用基类 checker 必然导航超时。
        与 :meth:`DecisiveMapController.enter_formation` 对称：checker
        直连 ``is_decisive_map_page``，source/target 仅作日志标签。
        """
        _log.debug('[UI] 决战出征准备 → 回退')
        click_and_wait_for_page(
            self._ctrl,
            click_coord=CLICK_BACK,
            checker=is_decisive_map_page,
            config=NavConfig(timeout=10.0, interval=0.5, max_retries=3),
            source='出征准备',
            target='决战地图',
            stop_event=self._ctx.stop_event,
        )
